package com.codepilot1c.core.tools.development;
import java.util.*;import java.util.concurrent.CompletableFuture;
import com.google.gson.*;
import com.codepilot1c.core.tools.*;
import com.codepilot1c.core.edt.development.*;
import com.codepilot1c.core.tools.workspace.BackgroundJobRegistry;
@ToolMeta(name="edt_ui_run",category="qa",mutating=true,tags={"workspace","edt","sensitive"})
public final class EdtUiRunTool extends AbstractTool {
 public String getDescription(){return "Unified direct UI run via edt.run op=ui. start requires explicit project/base_uuid/idempotency_key and1..16 TestClient steps, each with exact expected_window; mutations require expect and the final step must assert a result. Preflights before launch, then existing runtime preparation, pinned internal task-session, initial snapshot, one journaled batch, concise report and owned-resource cleanup (default true). For a30s map choose operation_timeout_s90 for the whole batch and wait_timeout_ms60000 on its step; defaults remain25s overall and10s explicit postcondition. No DB update/binding/trust changes, arbitrary BSL, endpoint override, automatic fallback or mutation replay. Native/Vanessa remain separate tools for unsupported scenarios. capture=on_failure(default)|final|final_and_failure|none captures only up to4 visible windows of the owned PID without foreground changes; blank images do not prove readiness. status is concise historical progress/result; details preserves the complete result before client cleanup. Startup timings/slowest phase and owned process/window diagnostics included. Same key observes original attempt; another key cannot bypass unknown outcomes or pending cleanup. Automatic cleanup removes owned clients/environments, NOT business records or base/project; session receipts and artifacts are retained. Manual cleanup_preview/cleanup requires plan_sha256. Poll job through edt_operation_status with timeout_ms instead of resubmitting.";}
 public String getParameterSchema(){var schema=JsonParser.parseString("""
 {"type":"object","additionalProperties":false,"required":["action"],"properties":{"action":{"enum":["start","status","details","cleanup_preview","cleanup"]},"project":{"type":"string"},"base_uuid":{"type":"string"},"idempotency_key":{"type":"string","maxLength":256},"client_kind":{"enum":["thin","thick"],"default":"thin"},"readiness_timeout_s":{"type":"integer","minimum":10,"maximum":180,"default":90},"capture":{"enum":["none","final","on_failure","final_and_failure"],"default":"on_failure"},"auto_cleanup":{"type":"boolean","default":true},"operation_timeout_s":{"type":"integer","minimum":5,"maximum":300,"default":25},"ui_run_id":{"type":"string","pattern":"^ui-[a-f0-9]{64}$"},"expected_plan_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}}}
 """).getAsJsonObject();schema.getAsJsonObject("properties").add("steps",JsonParser.parseString(new EdtFormActionTool().getParameterSchema()).getAsJsonObject().getAsJsonObject("properties").get("steps"));return schema.toString();}
 protected CompletableFuture<ToolResult> doExecute(ToolParameters p){try{for(String tool:UiRunBackend.dependencies())UiRunBackendPermission.check(tool);var s=UiRunService.workspace();var a=new LinkedHashMap<>(p.getRaw());String action=p.requireString("action");a.remove("action");Object out;
  if(action.equals("start"))out=s.start(a);
  else{if(!(action.equals("cleanup")?Set.of("ui_run_id","expected_plan_sha256"):Set.of("ui_run_id")).containsAll(a.keySet()))throw new IllegalArgumentException("Field does not apply to action");String id=p.requireString("ui_run_id");out=switch(action){case "status"->s.status(id);case "details"->s.details(id);case "cleanup_preview"->s.cleanupPreview(id);case "cleanup"->Map.of("job_id",BackgroundJobRegistry.getInstance().startJob("ui-run-cleanup",()->new Gson().toJson(s.cleanup(id,p.requireString("expected_plan_sha256")))),"ui_run_id",id,"next_tool","edt_operation_status");default->throw new IllegalArgumentException("Unknown UI run action");};}
  return CompletableFuture.completedFuture(ToolResult.success(new GsonBuilder().serializeNulls().create().toJson(out)));
 }catch(Exception e){return CompletableFuture.completedFuture(ToolResult.failure("edt_ui_run: "+(e instanceof IllegalArgumentException?e.getMessage():e.getClass().getSimpleName()+"; inspect original run and contract")));}}
 private static class UiRunBackendPermission {static void check(String tool){var cfg=com.codepilot1c.core.mcp.host.McpHostConfigStore.getInstance().load();if(cfg.getMutationPolicy()!=com.codepilot1c.core.mcp.host.McpHostConfig.MutationPolicy.ALLOW||!new com.codepilot1c.core.mcp.host.DefaultMcpToolExposurePolicy(cfg).isExposed(tool))throw new IllegalStateException("Dependency unavailable");}}
}
